const { ApolloServer } = require('@apollo/server');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');
const { prisma } = require('../db');

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

  type BillingAccount @key(fields: "id") {
    id: ID!
    accountNumber: String!
    currentBalance: Float!
    taxIdentifier: String!
    paymentMethodToken: String
  }
`;

const resolvers = {
  BillingAccount: {
    __resolveReference: async (reference, context) => {
      if (!context.user) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }
      const account = await prisma.billingAccount.findFirst({
        where: {
          id: reference.id,
          organizationId: context.user.organizationId,
        },
      });
      if (!account) {
        throw new GraphQLError('Billing account not found or access denied', { extensions: { code: 'FORBIDDEN' } });
      }
      return account;
    },
  },
};

const server = new ApolloServer({
  schema: buildSubgraphSchema([{ typeDefs, resolvers }]),
});
